'use strict';
// Version 2.6: Alltagsdilemmata und Philosophen-Karten (Deutsch). Die englische Fassung steht in denken.en.js,
// geladen wird nur die gewählte Sprache. IDs sind in beiden Sprachen gleich (Vorsilben a- und p-, Konzept 9.1).
//
// Alltag (kind 'alltag'):
//   opts   [{ t: Text, l: Blickwinkel }] mit l = 'F' Ergebnis, 'R' Grundsätze, 'C' Haltung (nur Orientierung für die Auflösung)
//   why    drei Gründe für „Was gibt für dich den Ausschlag?“ (gespeichert als w)
//   lenses die Auflösung aus drei Blickwinkeln
//   care   Themenhinweis, der vor der Frage erscheint (mit „Überspringen“); hint = leichter Hinweis ohne Sperre
//   calm   Satz am Anfang der Auflösung; help = Hilfe-Satz darunter; fact = „Gut zu wissen“ (geprüft, siehe PR)
// Philosophen (kind 'philo'):
//   opts   Antworten als Text; voices = [{ who, says, read, fit: [Antwort-Nummern ab 0], dispute }], fit [] = eigener Weg
//   stats  „So sehen es Fachleute“ (nur belegte Zahlen)
// pair: verwandte Fälle (auch 'tg:…' = Trolley-Klassiker) für den späteren Widerspruchs-Finder, noch ohne Anzeige.

