    hume: { name: 'David Hume', years: '1711–1776', looks: 'vertraut dem Gefühl', idea: 'Nicht die Vernunft, sondern das Gefühl bestimmt, was wir gut finden.', wiki: 'David Hume' },
    rawls: { name: 'John Rawls', years: '1921–2002', looks: 'fragt nach Gerechtigkeit', idea: 'Gerecht ist eine Ordnung, der alle zustimmen könnten, ohne zu wissen, wo sie darin selbst stehen.', wiki: 'John Rawls' },
